#!/usr/bin/env node
// Concatenate the portable classifier and this host's pure modules into
// one Apps Script file. const/let are file-scoped in Apps Script, so the
// classifier would be invisible to Code.js if the files were pushed apart.
// The sources under flow-trial-extension/ are read only. This script does
// not modify them.

const fs = require('fs');
const path = require('path');

const repo = path.join(__dirname, '..', '..');
const core = path.join(repo, 'flow-trial-extension', 'core');
const src = path.join(__dirname, '..', 'src');
const out = path.join(__dirname, '..', 'CoreBundle.js');

const files = [
  'domains.js',
  'extract.js',
  'judgment.js',
  'google-closes.js',
  'close-families.js',
  'fact-reply.js',
  'file-attach.js',
  'intent.js',
  'actions.js',
  'resolution.js',
  'system-notice.js',
  'incoming-judge.js'
].map((name) => path.join(core, name)).concat([
  'i18n.js',
  'urls.js',
  'intent.js',
  'proof.js',
  'execute.js',
  'cards.js',
  'prefetch.js',
  'remote.js'
].map((name) => path.join(src, name)));

const header = [
  '// Generated by glance-gmail-addon/scripts/build-bundle.js.',
  '// Do not edit. Re-run the script after changing the classifier or src/.',
  '// Apps Script runs this file in the Google account that installed the card.',
  '// It does not send mail.',
  ''
].join('\n');

const footer = [
  '',
  'var Glance = {',
  '  i18n: GlanceI18n,',
  '  urls: GlanceUrls,',
  '  intent: GlanceIntent,',
  '  proof: GlanceProof,',
  '  execute: GlanceExecute,',
  '  cards: GlanceCards,',
  '  prefetch: GlancePrefetch,',
  '  remote: GlanceRemote,',
  '  classify: function (text, ctx) { return FlowIntent.classify(text, ctx || {}); },',
  '  plan: function (intent, ctx) { return FlowActions.planFor(intent, ctx || {}); },',
  '  judge: function (input) { return FlowIncomingJudge.judge(input || {}, {}); }',
  '};',
  ''
].join('\n');

const parts = files.map((file) => {
  return '// ----- ' + path.relative(repo, file) + ' -----\n' + fs.readFileSync(file, 'utf8').replace(/\s+$/, '') + '\n';
});

fs.writeFileSync(out, header + parts.join('\n') + footer);
console.log('wrote ' + path.relative(repo, out) + ' (' + files.length + ' sources)');
